public static class Words
{
    public static int Count(ReadOnlySpan<char> text)
    {
        int count = 0;
        bool inWord = false;
        foreach (char c in text)
        {
            if (char.IsWhiteSpace(c)) inWord = false;
            else if (!inWord) { inWord = true; count++; }
        }
        return count;
    }
}

unitTests:
Test("counts", () =>
{
    CheckEq(Words.Count("  the quick\tbrown\nfox  "), 4);
    CheckEq(Words.Count(""), 0);
    CheckEq(Words.Count("   "), 0);
    CheckEq(Words.Count("one"), 1);
    CheckEq(Words.Count("a b c d e".AsSpan(2, 5)), 3);
});

